48         //------------------------------------------------------------------------------
49         // 2D rectangle
50         struct Rectangle
51         {
52             long x;
53             long y;
54             long width;
55             long height;
56 
57             // Creators
58             Rectangle() noexcept : x(0), y(0), width(0), height(0) {}
59             constexpr Rectangle(long ix, long iy, long iw, long ih) noexcept : x(ix), y(iy), width(iw), height(ih) {}
60             explicit Rectangle(const RECT& rct) noexcept : x(rct.left), y(rct.top), width(rct.right - rct.left), height(rct.bottom - rct.top) {}
61 
62             Rectangle(const Rectangle&) = default;
63             Rectangle& operator=(const Rectangle&) = default;
64 
65             Rectangle(Rectangle&&) = default;
66             Rectangle& operator=(Rectangle&&) = default;
67 
68             operator RECT() noexcept { RECT rct; rct.left = x; rct.top = y; rct.right = (x + width); rct.bottom = (y + height); return rct; }
69         #ifdef __cplusplus_winrt
70             operator Windows::Foundation::Rect() noexcept { return Windows::Foundation::Rect(float(x), float(y), float(width), float(height)); }
71         #endif
72 
73             // Comparison operators
74         #if (__cplusplus >= 202002L)
75             bool operator == (const Rectangle&) const = default;
76             auto operator <=> (const Rectangle&) const = default;
77         #else
78             bool operator == (const Rectangle& r) const noexcept { return (x == r.x) && (y == r.y) && (width == r.width) && (height == r.height); }
79             bool operator != (const Rectangle& r) const noexcept { return (x != r.x) || (y != r.y) || (width != r.width) || (height != r.height); }
80         #endif
81             bool operator == (const RECT& rct) const noexcept { return (x == rct.left) && (y == rct.top) && (width == (rct.right - rct.left)) && (height == (rct.bottom - rct.top)); }
82             bool operator != (const RECT& rct) const noexcept { return (x != rct.left) || (y != rct.top) || (width != (rct.right - rct.left)) || (height != (rct.bottom - rct.top)); }
83 
84             // Assignment operators
85             Rectangle& operator=(_In_ const RECT& rct) noexcept { x = rct.left; y = rct.top; width = (rct.right - rct.left); height = (rct.bottom - rct.top); return *this; }
86 
87             // Rectangle operations
88             Vector2 Location() const noexcept;
89             Vector2 Center() const noexcept;
90 
91             bool IsEmpty() const noexcept { return (width == 0 && height == 0 && x == 0 && y == 0); }
92 
93             bool Contains(long ix, long iy) const noexcept { return (x <= ix) && (ix < (x + width)) && (y <= iy) && (iy < (y + height)); }
94             bool Contains(const Vector2& point) const noexcept;
95             bool Contains(const Rectangle& r) const noexcept { return (x <= r.x) && ((r.x + r.width) <= (x + width)) && (y <= r.y) && ((r.y + r.height) <= (y + height)); }
96             bool Contains(const RECT& rct) const noexcept { return (x <= rct.left) && (rct.right <= (x + width)) && (y <= rct.top) && (rct.bottom <= (y + height)); }
97 
98             void Inflate(long horizAmount, long vertAmount) noexcept;
99 
100             bool Intersects(const Rectangle& r) const noexcept { return (r.x < (x + width)) && (x < (r.x + r.width)) && (r.y < (y + height)) && (y < (r.y + r.height)); }
101             bool Intersects(const RECT& rct) const noexcept { return (rct.left < (x + width)) && (x < rct.right) && (rct.top < (y + height)) && (y < rct.bottom); }
102 
103             void Offset(long ox, long oy) noexcept { x += ox; y += oy; }
104 
105             // Static functions
106             static Rectangle Intersect(const Rectangle& ra, const Rectangle& rb) noexcept;
107             static RECT Intersect(const RECT& rcta, const RECT& rctb) noexcept;
108 
109             static Rectangle Union(const Rectangle& ra, const Rectangle& rb) noexcept;
110             static RECT Union(const RECT& rcta, const RECT& rctb) noexcept;
111         };
