113         //------------------------------------------------------------------------------
114         // 2D vector
115         struct Vector2 : public XMFLOAT2
116         {
117             Vector2() noexcept : XMFLOAT2(0.f, 0.f) {}
118             constexpr explicit Vector2(float ix) noexcept : XMFLOAT2(ix, ix) {}
119             constexpr Vector2(float ix, float iy) noexcept : XMFLOAT2(ix, iy) {}
120             explicit Vector2(_In_reads_(2) const float *pArray) noexcept : XMFLOAT2(pArray) {}
121             Vector2(FXMVECTOR V) noexcept { XMStoreFloat2(this, V); }
122             Vector2(const XMFLOAT2& V) noexcept { this->x = V.x; this->y = V.y; }
123             explicit Vector2(const XMVECTORF32& F) noexcept { this->x = F.f[0]; this->y = F.f[1]; }
124 
125             Vector2(const Vector2&) = default;
126             Vector2& operator=(const Vector2&) = default;
127 
128             Vector2(Vector2&&) = default;
129             Vector2& operator=(Vector2&&) = default;
130 
131             operator XMVECTOR() const noexcept { return XMLoadFloat2(this); }
132 
133             // Comparison operators
134             bool operator == (const Vector2& V) const noexcept;
135             bool operator != (const Vector2& V) const noexcept;
136 
137             // Assignment operators
138             Vector2& operator= (const XMVECTORF32& F) noexcept { x = F.f[0]; y = F.f[1]; return *this; }
139             Vector2& operator+= (const Vector2& V) noexcept;
140             Vector2& operator-= (const Vector2& V) noexcept;
141             Vector2& operator*= (const Vector2& V) noexcept;
142             Vector2& operator*= (float S) noexcept;
143             Vector2& operator/= (float S) noexcept;
144 
145             // Unary operators
146             Vector2 operator+ () const noexcept { return *this; }
147             Vector2 operator- () const noexcept { return Vector2(-x, -y); }
148 
149             // Vector operations
150             bool InBounds(const Vector2& Bounds) const noexcept;
151 
152             float Length() const noexcept;
153             float LengthSquared() const noexcept;
154 
155             float Dot(const Vector2& V) const noexcept;
156             void Cross(const Vector2& V, Vector2& result) const noexcept;
157             Vector2 Cross(const Vector2& V) const noexcept;
158 
159             void Normalize() noexcept;
160             void Normalize(Vector2& result) const noexcept;
161 
162             void Clamp(const Vector2& vmin, const Vector2& vmax) noexcept;
163             void Clamp(const Vector2& vmin, const Vector2& vmax, Vector2& result) const noexcept;
164 
165             // Static functions
166             static float Distance(const Vector2& v1, const Vector2& v2) noexcept;
167             static float DistanceSquared(const Vector2& v1, const Vector2& v2) noexcept;
168 
169             static void Min(const Vector2& v1, const Vector2& v2, Vector2& result) noexcept;
170             static Vector2 Min(const Vector2& v1, const Vector2& v2) noexcept;
171 
172             static void Max(const Vector2& v1, const Vector2& v2, Vector2& result) noexcept;
173             static Vector2 Max(const Vector2& v1, const Vector2& v2) noexcept;
