1007     template<> struct less<DirectX::SimpleMath::Rectangle>
1008     {
1009         bool operator()(const DirectX::SimpleMath::Rectangle& r1, const DirectX::SimpleMath::Rectangle& r2) const noexcept
1010         {
1011             return ((r1.x < r2.x)
1012                 || ((r1.x == r2.x) && (r1.y < r2.y))
1013                 || ((r1.x == r2.x) && (r1.y == r2.y) && (r1.width < r2.width))
1014                 || ((r1.x == r2.x) && (r1.y == r2.y) && (r1.width == r2.width) && (r1.height < r2.height)));
1015         }
1016     };
