1047     template<> struct less<DirectX::SimpleMath::Matrix>
1048     {
1049         bool operator()(const DirectX::SimpleMath::Matrix& M1, const DirectX::SimpleMath::Matrix& M2) const noexcept
1050         {
1051             if (M1._11 != M2._11) return M1._11 < M2._11;
1052             if (M1._12 != M2._12) return M1._12 < M2._12;
1053             if (M1._13 != M2._13) return M1._13 < M2._13;
1054             if (M1._14 != M2._14) return M1._14 < M2._14;
1055             if (M1._21 != M2._21) return M1._21 < M2._21;
1056             if (M1._22 != M2._22) return M1._22 < M2._22;
1057             if (M1._23 != M2._23) return M1._23 < M2._23;
1058             if (M1._24 != M2._24) return M1._24 < M2._24;
1059             if (M1._31 != M2._31) return M1._31 < M2._31;
1060             if (M1._32 != M2._32) return M1._32 < M2._32;
1061             if (M1._33 != M2._33) return M1._33 < M2._33;
1062             if (M1._34 != M2._34) return M1._34 < M2._34;
1063             if (M1._41 != M2._41) return M1._41 < M2._41;
1064             if (M1._42 != M2._42) return M1._42 < M2._42;
1065             if (M1._43 != M2._43) return M1._43 < M2._43;
1066             if (M1._44 != M2._44) return M1._44 < M2._44;
1067 
1068             return false;
1069         }
1070     };
